INSERT INTO `products` (`id`, `name`, `category`, `price`, `stock`, `description`, `keywords`, `uu_diem`, `nhuoc_diem`, `phu_hop`) VALUES
(1, 'iPhone 15 Pro Max', 'Điện thoại', 34990000, 66, 'Apple A17 Pro, màn hình 6.7 inch Super Retina XDR, 256GB, camera 48MP, khung titan, USB-C', 'iphone 15 pro max điện thoại', 'Camera xuất sắc, chip mạnh nhất, hệ sinh thái Apple tốt, khung titan sang trọng, quay video 4K ProRes', 'Giá cao, không có sạc nhanh như Android, không hỗ trợ 2 SIM vật lý', 'Người dùng muốn camera tốt nhất, làm việc với hệ sinh thái Apple, quay video chuyên nghiệp'),
(2, 'iPhone 14 Plus', 'Điện thoại', 21500000, 99, 'Apple A15 Bionic, màn hình 6.7 inch, 128GB, camera kép 12MP, pin cả ngày', 'iphone 14 plus điện thoại', 'Pin trâu nhất dòng iPhone, màn hình lớn, hiệu năng ổn định, giá tốt hơn Pro', 'Camera không bằng Pro, chip đời cũ, không có Dynamic Island', 'Người cần iPhone màn hình lớn, pin lâu, không cần tính năng cao cấp'),
(3, 'Samsung Galaxy S24 Ultra', 'Điện thoại', 31990000, 67, 'Snapdragon 8 Gen 3, màn hình 6.8 inch Dynamic AMOLED 2X, 512GB, camera 200MP, bút S Pen, AI Galaxy', 'samsung galaxy s24 ultra điện thoại', 'Bút S Pen tiện lợi, camera zoom 100x, tính năng AI thông minh, màn hình đẹp nhất phân khúc', 'Nặng (232g), giá cao, một số tính năng AI cần internet', 'Người cần bút S Pen, chụp ảnh zoom xa, sử dụng AI, làm việc đa nhiệm'),
(4, 'Samsung Galaxy Z Fold 5', 'Điện thoại', 39990000, 43, 'Snapdragon 8 Gen 2, màn hình gập 7.6 inch + ngoài 6.2 inch, 256GB, đa nhiệm chia đôi màn hình', 'samsung galaxy z fold 5 điện thoại', 'Màn hình gập độc đáo, đa nhiệm tuyệt vời, trải nghiệm như tablet, công nghệ tiên phong', 'Giá rất cao, nặng, nếp gập vẫn thấy, camera không bằng S24 Ultra', 'Người thích công nghệ mới, cần đa nhiệm, muốn vừa điện thoại vừa tablet'),
(5, 'Xiaomi 14', 'Điện thoại', 18990000, 46, 'Snapdragon 8 Gen 3, màn hình 6.36 inch LTPO AMOLED, 256GB, camera Leica 50MP, sạc nhanh 90W', 'xiaomi 14 điện thoại', 'Hiệu năng mạnh, sạc siêu nhanh 90W (30 phút đầy), camera Leica chất lượng, giá hợp lý', 'Thương hiệu chưa phổ biến bằng Apple/Samsung, màn hình hơi nhỏ, ít phụ kiện chính hãng', 'Người muốn hiệu năng cao với giá tốt, thích sạc nhanh, chụp ảnh đẹp'),
(6, 'Xiaomi Redmi Note 13', 'Điện thoại', 5490000, 19, 'MediaTek Dimensity 6080, màn hình 6.67 inch AMOLED 120Hz, 128GB, camera 108MP', 'xiaomi redmi note 13 điện thoại', 'Giá rẻ nhất phân khúc, camera 108MP ấn tượng, màn hình 120Hz mượt mà, pin 5000mAh', 'Chip xử lý trung bình, chậm khi chơi game nặng, chất liệu nhựa', 'Sinh viên, người cần điện thoại giá rẻ mà vẫn chụp ảnh đẹp, màn hình tốt'),
(7, 'OPPO Find X7', 'Điện thoại', 21990000, 36, 'Dimensity 9300, màn hình 6.82 inch LTPO AMOLED, camera Hasselblad 50MP, sạc nhanh 100W', 'oppo find x7 điện thoại', 'Camera Hasselblad siêu đẹp, sạc cực nhanh 100W (17 phút đầy), màn hình lớn rất đẹp', 'Thương hiệu ít phổ biến, giá tương đối cao, hệ sinh thái phụ kiện hạn chế', 'Người yêu thích nhiếp ảnh, cần sạc nhanh, thích màn hình lớn'),
(8, 'MacBook Air M3', 'Laptop', 28990000, 86, 'Apple M3, 8GB RAM, 256GB SSD, màn hình Liquid Retina 13.6 inch, pin 18 giờ, nặng 1.24kg', 'macbook air m3 laptop', 'Siêu nhẹ siêu mỏng, pin 18 giờ cả ngày không cần sạc, chip M3 mạnh, fan-less không tiếng ồn', 'RAM 8GB khó nâng cấp, bộ nhớ 256GB hơi ít, không chơi game được, giá cao', 'Sinh viên, dân văn phòng, người cần laptop di động, làm việc nhẹ (văn phòng, web, design cơ bản)'),
(9, 'MacBook Pro 14 M3', 'Laptop', 39900000, 75, 'Apple M3 Pro, 18GB RAM, 512GB SSD, màn hình Liquid Retina XDR 14 inch, pin 17 giờ', 'macbook pro 14 m3 laptop', 'Màn hình XDR cực đẹp, hiệu năng pro cho video/code, pin siêu lâu, loa tuyệt vời', 'Giá rất cao, nặng hơn Air, không chơi game AAA', 'Dân lập trình, editor video, designer chuyên nghiệp, người cần hiệu năng cao'),
(10, 'Dell XPS 15', 'Laptop', 42000000, 36, 'Intel Core i7-13700H, 16GB RAM, RTX 4060, màn hình OLED 4K 15.6 inch, 512GB SSD', 'dell xps 15 laptop', 'Màn hình OLED 4K tuyệt đẹp, card rời RTX 4060 mạnh, thiết kế premium, bàn phím tốt', 'Giá cao, pin trung bình (6-8h), nóng khi chạy nặng, chỉ có 2 cổng USB-C', 'Designer đồ hoạ, editor video, dân sáng tạo cần màn hình đẹp và hiệu năng'),
(11, 'Asus ROG Zephyrus G14', 'Laptop', 38500000, 72, 'AMD Ryzen 9 7940HS, 16GB RAM, RTX 4060, màn hình 14 inch 165Hz, 512GB SSD, nặng 1.65kg', 'asus rog zephyrus g14 laptop', 'Laptop gaming nhẹ nhất (1.65kg), màn hình 165Hz mượt, hiệu năng gaming mạnh, thiết kế đẹp', 'Màn hình 14 inch hơi nhỏ cho game, loa trung bình, giá cao cho laptop 14 inch', 'Game thủ muốn laptop nhẹ để mang đi, người cần hiệu năng cao mà vẫn di động'),
(12, 'HP Envy 13', 'Laptop', 22990000, 21, 'Intel Core i5-1335U, 16GB RAM, 512GB SSD, màn hình 13.3 inch FHD IPS, nặng 1.3kg, pin 11 giờ', 'hp envy 13 laptop', 'Giá hợp lý, nhẹ 1.3kg, pin 11 giờ, thiết kế thanh lịch, bàn phím toàn chiều, vân tay nhanh', 'Không có card rời (không chơi game), màn hình chỉ FHD, hiệu năng xử lý trung bình', 'Sinh viên, nhân viên văn phòng, người cần laptop nhẹ giá tốt'),
(13, 'Lenovo ThinkPad X1 Carbon', 'Laptop', 35000000, 35, 'Intel Core i7-1365U, 16GB RAM, 1TB SSD, màn hình 14 inch 2.8K OLED, nặng 1.12kg, chuẩn quân đội MIL-STD', 'lenovo thinkpad x1 carbon laptop', 'Siêu nhẹ 1.12kg, bền chuẩn quân đội, bàn phím tốt nhất laptop, bảo mật vân tay + khuôn mặt', 'Giá cao, không có card rời, thiết kế kinh điển (không thời trang)', 'Doanh nhân, người đi công tác nhiều, cần laptop siêu nhẹ + siêu bền'),
(14, 'iPad Pro M2', 'Máy tính bảng', 25990000, 37, 'Apple M2, màn hình Mini-LED 11 inch, 256GB, hỗ trợ Apple Pencil 2, Magic Keyboard', 'ipad pro m2 máy tính bảng', 'Chip M2 mạnh như laptop, màn hình Mini-LED cực đẹp, Apple Pencil vẽ tuyệt vời, loa 4 phía', 'Giá cao, phụ kiện đắt (Pencil + Keyboard riêng), iPadOS vẫn hạn chế so với macOS', 'Hoạ sĩ số, sinh viên ghi chú, người xem phim/đọc sách, designer cần vẽ tay'),
(15, 'Samsung Galaxy Tab S9', 'Máy tính bảng', 19990000, 69, 'Snapdragon 8 Gen 2, màn hình 11 inch Dynamic AMOLED, 128GB, S Pen đi kèm, kháng nước IP68', 'samsung galaxy tab s9 máy tính bảng', 'S Pen đi kèm (không mua thêm), kháng nước IP68, màn hình AMOLED đẹp, Samsung DeX chế độ desktop', 'Hệ sinh thái ứng dụng tablet Android chưa bằng iPad, loa chỉ 2 phía', 'Người dùng Android, cần tablet chống nước, ghi chú bằng bút, xem phim màn hình đẹp'),
(16, 'Tai nghe Sony WH-1000XM5', 'Tai nghe', 8490000, 49, 'Chống ồn chủ động (ANC) hàng đầu, pin 30 giờ, Bluetooth 5.2, driver 30mm, nặng 250g, sạc nhanh 3 phút = 3 giờ nghe', 'tai nghe sony wh-1000xm5 tai nghe', 'Chống ồn tốt nhất thị trường, âm thanh tuyệt vời, pin 30h siêu lâu, đeo thoải mái, micro gọi tốt', 'Giá cao, không gập được (khó mang đi), không chống nước', 'Người làm việc văn phòng, đi máy bay thường xuyên, audiophile, người cần tập trung'),
(17, 'AirPods Pro 2', 'Tai nghe', 6490000, 91, 'Chip H2, chống ồn chủ động, chế độ trong suốt, chống nước IP54, sạc MagSafe, pin 6h (30h với hộp)', 'airpods pro 2 tai nghe', 'Nhỏ gọn, chống ồn tốt, tích hợp tuyệt vời với iPhone/Mac/iPad, chống nước, tìm bằng Find My', 'Chỉ tốt nhất với thiết bị Apple, pin tai nghe chỉ 6h, giá cao cho tai nghe true wireless', 'Người dùng iPhone/Apple, cần tai nghe nhỏ gọn, tập gym, di chuyển nhiều'),
(18, 'Chuột Logitech MX Master 3S', 'Phụ kiện', 1990000, 38, 'Không dây Bluetooth + USB receiver, cảm biến 8000 DPI, pin sạc 70 ngày, cuộn trang siêu nhanh MagSpeed', 'chuột logitech mx master 3s phụ kiện', 'Ergonomic cực thoải mái, pin 70 ngày, kết nối 3 thiết bị cùng lúc, cuộn trang siêu nhanh', 'Giá cao cho chuột, hơi nặng, không phù hợp chơi game', 'Dân văn phòng, designer, lập trình viên, người dùng nhiều giờ mỗi ngày'),
(19, 'Bàn phím Keychron K2 Pro', 'Phụ kiện', 2490000, 90, 'Cơ học 75%, Bluetooth 5.1 + USB-C, hot-swap switch, đèn RGB, tương thích Mac và Windows, pin sạc', 'bàn phím keychron k2 pro phụ kiện', 'Hot-swap thay switch dễ dàng, cơ học gõ rất đã, RGB đẹp, kết nối cả Bluetooth và dây', 'Hơi nặng, âm thanh gõ có thể ồn ào, cần thời gian làm quen layout 75%', 'Người thích bàn phím cơ, lập trình viên, game thủ, người muốn trải nghiệm gõ phím premium'),
(20, 'Màn hình LG 27 inch 4K', 'Màn hình', 12990000, 84, 'Tấm nền IPS 27 inch, độ phân giải 4K UHD, HDR400, cổng USB-C 60W (sạc laptop), 60Hz', 'màn hình lg 27 inch 4k màn hình', '4K sắc nét, USB-C 60W vừa hiển thị vừa sạc laptop, màu sắc chính xác 99% sRGB, góc nhìn rộng IPS', 'Chỉ 60Hz (không tốt cho game), HDR400 trung bình, giá cao hơn Full HD nhiều', 'Designer, lập trình viên, dân văn phòng cần màn hình đẹp, người dùng MacBook cần màn hình phụ');
